import zipfile
import re
from xml.etree import ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/officeDocument/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    letters = m.group(1)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - 64)
    return idx

def get_text(el, tag):
    node = el.find(tag, NS)
    return node.text if node is not None else None

z = zipfile.ZipFile('budget.xlsx')
names = z.namelist()

# shared strings
shared = []
if 'xl/sharedStrings.xml' in names:
    root = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in root.findall('m:si', NS):
        parts = [t.text or '' for t in si.iter('{%s}t' % NS['m'])]
        shared.append(''.join(parts))

# workbook sheets + rels
wb_root = ET.fromstring(z.read('xl/workbook.xml'))
rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
rid_to_target = {}
for rel in rels_root.findall('{%s}Relationship' % NS['r']):
    rid_to_target[rel.get('Id')] = rel.get('Target')

sheets = []
for sh in wb_root.find('m:sheets', NS):
    rid = sh.get('{%s}id' % NS['r'])
    sheets.append((sh.get('name'), rid_to_target.get(rid, '')))

for name, target in sheets:
    path = 'xl/' + target if not target.startswith('xl/') else target
    if path not in names:
        continue
    print('=' * 60)
    print('SHEET:', name)
    print('=' * 60)
    root = ET.fromstring(z.read(path))
    rows = {}
    for c in root.iter('{%s}c' % NS['m']):
        ref = c.get('r')
        t = c.get('t')
        v = c.find('m:v', NS)
        is_ = c.find('m:is', NS)
        val = None
        if t == 's' and v is not None:
            val = shared[int(v.text)]
        elif t == 'inlineStr' and is_ is not None:
            val = ''.join(x.text or '' for x in is_.iter('{%s}t' % NS['m']))
        elif t == 'str' and v is not None:
            val = v.text
        elif t == 'b' and v is not None:
            val = v.text
        elif v is not None:
            val = v.text
        if val is not None:
            rows[ref] = val
    if not rows:
        continue
    # print dense grid
    all_refs = sorted(rows.keys(), key=lambda r: (int(re.match(r'[A-Z]+(\d+)', r).group(1)), col_to_idx(r)))
    # group by row
    by_row = {}
    for ref in all_refs:
        rn = int(re.match(r'[A-Z]+(\d+)', ref).group(1))
        by_row.setdefault(rn, {})[col_to_idx(ref)] = rows[ref]
    for rn in sorted(by_row):
        cells = by_row[rn]
        line = []
        for ci in sorted(cells):
            line.append('%s=%r' % (ci, cells[ci]))
        print('ROW %d: %s' % (rn, ' | '.join(line)))
